def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != 3:
                continue
            # A small motif centered at each 3, with a full-width baseline.
            if r - 2 >= 0:
                for x in range(max(0, c - 2), min(w, c + 3)):
                    out[r - 2][x] = 5
            for y in (r - 1, r, r + 1):
                if 0 <= y < h:
                    for x in (c - 2, c + 2):
                        if 0 <= x < w:
                            out[y][x] = 2
            if 0 <= r - 1 < h and 0 <= c < w:
                out[r - 1][c] = 5
            if 0 <= r + 2 < h:
                for x in range(w):
                    out[r + 2][x] = 2
                for x in range(max(0, c - 2), min(w, c + 3)):
                    out[r + 2][x] = 8
    return out
